"""Small HTML rendering layer: a Jinja2 environment with a few helpers."""
import jinja2
from jinja2 import contextfunction, evalcontextfilter

TEMPLATES = {
    "page.html": (
        "<h1>{{ title }}</h1>"
        "{{ badge(user) }}"
        "<ul>{% for item in items %}<li>{{ item|shout }}</li>{% endfor %}</ul>"
        "<p>{{ note|nl2br }}</p>"
        "{% with total = items|length %}<small>{{ total }} items</small>{% endwith %}"
    ),
    "row.html": "<td>{{ cell }}</td>",
}


@contextfunction
def badge(ctx, name):
    prefix = ctx.get("badge_prefix", "@")
    return jinja2.Markup('<span class="badge">%s%s</span>') % (prefix, name)


@evalcontextfilter
def shout(eval_ctx, value):
    text = str(value).upper() + "!"
    if eval_ctx.autoescape:
        return jinja2.Markup(jinja2.escape(text))
    return text


def nl2br(value):
    lines = str(value).splitlines()
    return jinja2.Markup("<br>").join(jinja2.escape(line) for line in lines)


def make_env(autoescape=True):
    env = jinja2.Environment(
        loader=jinja2.DictLoader(TEMPLATES),
        autoescape=autoescape,
        extensions=["jinja2.ext.with_"],
        undefined=jinja2.StrictUndefined,
    )
    env.globals["badge"] = badge
    env.filters["shout"] = shout
    env.filters["nl2br"] = nl2br
    return env


def render_page(title, items, user, note="", autoescape=True):
    env = make_env(autoescape)
    return env.get_template("page.html").render(
        title=title, items=items, user=user, note=note
    )


def render_string(source, **context):
    return make_env().from_string(source).render(**context)


def render_row(cell):
    try:
        return make_env().get_template("row.html").render(cell=cell)
    except jinja2.TemplateNotFound:
        return ""


def safe_label(text):
    """Escape user text for use inside markup built by hand."""
    return jinja2.Markup("<b>") + jinja2.escape(text) + jinja2.Markup("</b>")
